import hashlib,json,sys; from pathlib import Path; import numpy as np; from PIL import Image; a=Path(sys.argv[1]); b=Path(sys.argv[2]); rows=[];
for name in ["mask.png","overlay.png","composite.png"]:
 x=np.asarray(Image.open(a/name)); y=np.asarray(Image.open(b/name)); assert np.array_equal(x,y),name; rows.append({"file":name,"shape":list(x.shape),"pixel_equal":True,"sha256_equal":hashlib.sha256((a/name).read_bytes()).hexdigest()==hashlib.sha256((b/name).read_bytes()).hexdigest()})
x=json.loads((a/"metadata.json").read_text()); y=json.loads((b/"metadata.json").read_text()); assert x==y,(x,y); print(json.dumps({"images":rows,"metadata_equal":True,"checkpoint_sha256":x["checkpoint_sha256"],"decision_sha256":x["decision_sha256"]}))
